<?phpif (defined('WATCHERS')==false) die('1');function molch($persto,$perswho,$duration,$reason){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if ( empty($reason) ) $reason = ' отсутствует';	if ($duration>-1)	{		if ($duration==5) $timemolch = '5 минут';		if ($duration==10) $timemolch = '10 минут';		if ($duration==15) $timemolch = '15 минут';		if ($duration==30) $timemolch = '30 минут';		if ($duration==60) $timemolch = '1 час';		if ($duration==120) $timemolch = '2 часa';		if ($duration==180) $timemolch = '3 часa';		if ($duration==360) $timemolch = '6 часов';		if ($duration==720) $timemolch = '12 часов';		if ($duration==1440) $timemolch = 'сутки';		echo 'Персонаж <b>'.$persto['user'].'</b> замолчал на '.$timemolch.' (<b>'.$perswho['user'].'</b>). <b>Причина: </b>'.$reason;		say_to_chat('z','Персонаж <b>'.$tologn.'</b> будет молчать '.$timemolch." (<b>".$ispoln."</b>). <b>Причина: </b>".$reason,0,'','*',0); 		$a['image'] = 'molch';		$a['params'] = '';		$a['esttime'] = $duration*60;		$a['name'] = 'Заклинание молчания';		$a['special'] = 1;		light_aura_on($a,$persto['uid']);		set_vars ("silence=".(tme()+$a['esttime']),$persto['uid']);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '1', '".$reason."', '".($duration*60)."');");		$persto['kindness'] -= $duration/100*(1+mtrunc(-1*$persto['kindness']));		set_vars("kindness=".$persto['kindness'],$persto['uid']);	}	elseif ($persto['silence']>tme())	{		echo 'C персонажа <b>'.$persto['user'].'</b> снято заклинание молчания (<b>'.$perswho['user'].'</b>)';		say_to_chat('z','Персонаж <b>'.$tologn.'</b> снова обрёл дар речи (<b>'.$ispoln.'</b>).',0,'','*',0); 		$db->sql("UPDATE `p_auras` SET `esttime`=0 WHERE `uid`=".$persto['uid']." and `special`=1");		set_vars ("`silence`=0", $persto['uid']);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '11');");	}}function punish($persto,$perswho,$duration,$reason){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if (empty($reason)) $reason = ' отсутствует';	if ($duration>-1)	{		if ($duration==5) $timemolch = '5 минут';		if ($duration==10) $timemolch = '10 минут';		if ($duration==15) $timemolch = '15 минут';		if ($duration==30) $timemolch = '30 минут';		if ($duration==60) $timemolch = '1 час';		if ($duration==360) $timemolch = '6 часов';		if ($duration==1440) $timemolch = 'сутки';		if ($duration==2880) $timemolch = 'двое суток';		echo '<b>'.$perswho['user'].'</b> покарал <b>'.$persto['user'].'</b> на '.$timemolch.'. <b>Причина:</b>'.$reason;		say_to_chat('z','<b>'.$ispoln.'</b> покарал <b>'.$tologn.'</b> на '.$timemolch.'.<b>Причина: </b>'.$reason,0,'','*',0); 		set_vars("punishment=".(tme()+$duration*60)."",$persto['uid']);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '4', '".$reason."', '".($duration*60)."');");		$persto['kindness'] -= 1/(1+mtrunc(-1*$persto['kindness']));		set_vars("kindness=".$persto['kindness'],$persto['uid']);	}	else	{		echo 'C персонажа <b>'.$persto['user'].'</b> снято заклинание кары смотрителей (<b>'.$perswho['user'].'</b>)';		say_to_chat('z','C персонажа <b>'.$tologn.'</b> снято заклинание кары Смотрителей (<b>'.$ispoln.'</b>).',0,'','*',0); 		set_vars ("punishment=0",$persto['uid']);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '10', '', '');");	}}function prison($persto,$perswho,$duration,$reason){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if ($duration>0)	{		$duration *= 86400;		set_vars ("curstate=2,location='prison',prison='".($duration+tme())."|".$reason."'",$persto['uid']);		echo 'Персонаж <b>'.$persto['user'].'</b> попал в тюремное заточение (<b>'.$perswho['user'].'</b>). <b>Причина:</b> '.$reason;		say_to_chat('z','Персонаж <b>'.$tologn.'</b> попал в тюремное заточение (<b>'.$ispoln.'</b>). <b>Причина:</b> '.$reason,0,'','*',0); 		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '3', '".$reason."', '".$duration."');");		$persto['kindness'] -= 1/(1+mtrunc(-1*$persto['kindness']));		set_vars("kindness=".$persto['kindness'],$persto['uid']);	}	else	{		echo 'Персонаж <b>'.$persto['user'].'</b> выпущен из тюрьмы (<b>'.$perswho['user'].'</b>)';		say_to_chat('z','Персонаж <b>'.$tologn.'</b> выпущен из тюрьмы (<b>'.$ispoln.'</b>).',0,'','*',0); 		set_vars ("prison=''",$persto['uid']);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '8', '', '');");	}}function pometka($persto,$perswho,$p){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	set_vars ("block='".$reason."'",$persto['uid']);	echo 'Оставлена пометка: <b>'.$p.'</b>';	say_to_chat('z','<b>'.$ispoln.'</b> оставил о вас пометку: <b>'.$p.'</b>',1,$persto['user'],'*',0); 	$db->sql("INSERT INTO `watch_pometca` (`uid`, `date`, `text`, `who`, `whoid`) VALUES (".$persto['uid'].", ".tme().", '".$p."', '".pers_pack($perswho)."', ".$perswho['uid'].");");}function block($persto,$perswho,$duration,$reason){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if ($duration<>2)	{		set_vars ("block='".$reason."'",$persto['uid']);		echo 'На <b>'.$persto['user'].'</b> наложено заклинание смерти, спи спокойно! (<b>'.$perswho['user'].'</b>). <b>Причина:</b> '.$reason;		say_to_chat('z','На <b>'.$tologn.'</b> наложено заклинание смерти, спи спокойно! (<b>'.$ispoln.'</b>). <b>Причина:</b> '.$reason,0,'','*',0); 		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '2', '".$reason."', '0');");	}	else	{		echo 'Персонаж <b>'.$persto['user'].'</b> оживлён! (<b>'.$perswho['user'].'</b>)';		say_to_chat('z','Персонаж <b>'.$tologn.'</b> оживлён! (<b>'.$ispoln.'</b>)',0,'','*',0); 		set_vars ("block=''",$persto['uid']);		$db->sql("UPDATE puns SET duration=".(tme()-$persto['lastom'])." WHERE duration=0 and type=2 and uid=".$persto['uid']."");		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '9', '', '');");	}}function blocki($persto,$perswho,$reason){	GLOBAL $db;	echo 'На персонажа <b>'.$persto['user'].'</b> наложено заклинание блокирование информации(<b>'.$perswho['user'].'</b>)';	$db->sql ("UPDATE `chars` SET `about`='Заблокировано. Причина: ".$reason."' WHERE `uid`=".$persto['uid']);	$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '5', '".$reason."', '0');");}function maridge($persto,$perswho,$m){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$M = $db->sqla("SELECT `user`,`pol`,`uid` FROM `users` WHERE `user` = '".$m."' and `pol`<>'".$persto['pol']."'");	if($M['uid']==true)	{		set_vars ("`maridge`='".$M['uid']."'",$persto['uid']);		set_vars ("`maridge`='".$persto['uid']."'",$M['uid']);		echo 'Вы удачно поженили <b>'.$persto['user'].'</b> и <b>'.$M['user'].'</b>.';		say_to_chat('a','Внимание! У нас свадьба. Дорогие <b>'.$persto['user'].'</b> и <b>'.$M['user'].'</b>, желаем счастья, любви и общих побед! (<b>'.$ispoln.'</b>)',0,'','*',0); 	}	else	{		echo "Нет такого персонажа, или одинаковый пол.";	}}function benediction($persto,$perswho,$duration,$reason){	GLOBAL $db;	if ($perswho['user'] == $persto['user']) return;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if (empty($reason)) $reason = ' отсутствует';	$aur_wt = $db->sqla_id("SELECT `esttime` FROM `p_auras` WHERE `uid`=".$persto['uid']." and `special`=77 and `esttime`>".tme());	if ( $duration>-1 and ($aur_wt[0]==false or $aur_wt[0]<$persto['lastom']) )	{		if ($duration==5) $timemolch = '5 минут';		if ($duration==10) $timemolch = '10 минут';		if ($duration==15) $timemolch = '15 минут';		if ($duration==30) $timemolch = '30 минут';		if ($duration==60) $timemolch = '1 час';		if ($duration==360) $timemolch = '6 часов';		if ($duration==1440) $timemolch = 'сутки';		if ($duration==2880) $timemolch = 'двое суток';		echo '<b>'.$perswho['user'].'</b> благославил <b>'.$persto['user'].'</b> на '.$timemolch.'. <b> Причина:</b>'.$reason;		say_to_chat('z','<b>'.$ispoln.'</b> благословил <b>'.$tologn.'</b> на '.$timemolch.'.<b> Причина: </b>'.$reason,0,'','*',0); 				$wtkb = ($persto['level']<5) ? 100 : floor($persto['kb']*0.5);		$wtudmin = ($persto['level']<5) ? 20 : floor($persto['udmin']*0.3);		$wtudmax = ($persto['level']<5) ? 25 : floor($persto['udmax']*0.3);		$wts1 = ($persto['level']<5) ? 5 : floor($persto['s1']*0.5);		$wts2 = ($persto['level']<5) ? 5 : floor($persto['s2']*0.5);		$wts3 = ($persto['level']<5) ? 5 : floor($persto['s3']*0.5);		$wts4 = ($persto['level']<5) ? 5 : floor($persto['s4']*0.5);		$wts5 = ($persto['level']<5) ? 5 : floor($persto['s5']*0.5);		$wts6 = ($persto['level']<5) ? 5 : floor($persto['s6']*0.5);				$persto['kb']+=$wtkb;		$persto['udmin']+=$wtudmin;		$persto['udmax']+=$wtudmax;		$persto['s1']+=$wts1;		$persto['s2']+=$wts2;		$persto['s3']+=$wts3;		$persto['s4']+=$wts4;		$persto['s5']+=$wts5;		$persto['s6']+=$wts6;				$a['image'] = 'mag_blago';		$a['params'] = 'kb='.$wtkb.'@udmin='.$wtudmin.'@udmax='.$wtudmax.'@s1='.$wts1.'@s2='.$wts2.'@s3='.$wts3.'@s4='.$wts4.'@s5='.$wts5.'@s6='.$wts6.'@';		$a['esttime'] = $duration*60;		$a['name'] = 'Благословление Смотрителей';		$a['special'] = 77; ### Благословение				$persto['kindness'] += 1/(1+mtrunc(-1*$persto['kindness']));				light_aura_on($a,$persto['uid']);		set_vars(aq($persto),$persto["uid"]);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '15', '".$reason."', '".($duration*60)."');");	}	else	{		if ( $aur_wt[0]>tme() and $duration==-1)		{			echo 'C персонажа <b>'.$persto['user'].'</b> снято Благословление Смотрителей (<b>'.$perswho['user'].'</b>)';			say_to_chat('z','C персонажа <b>'.$tologn.'</b> снято Благословление Смотрителей (<b>'.$ispoln.'</b>).',0,'','*',0); 			$db->sql("UPDATE `p_auras` SET `esttime`=".tme()." WHERE `uid`=".$persto['uid']." and `special`=77");			$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '16', '', '');");		} else echo 'Ошибка.';	}}function fmolch($persto,$perswho,$duration,$reason){	GLOBAL $db;	$ispoln = ($perswho['invisible']>tme()) ? '<i>невидимка</i>' : $perswho['user'];	$tologn = ($persto['invisible']>tme()) ? '<i>невидимка</i>' : $persto['user'];	if ( empty($reason) ) $reason = ' отсутствует';	if ($duration>-1)	{		if ($duration==1) $timemolch = '1 день';		if ($duration==3) $timemolch = '3 дня';		if ($duration==7) $timemolch = '1 неделя';		if ($duration==14) $timemolch = '2 недели';		if ($duration==30) $timemolch = '1 месяц';		if ($duration==60) $timemolch = '2 месяца';		if ($duration==365) $timemolch = '1 год';		$tm = (3600*24*$duration);		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` , `reason` , `duration` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '17', '".$reason."', '".$tm."');");		set_vars ('`silence_forum`='.(tme()+$tm), $persto['uid']);		say_to_chat('z','Персонаж <b>'.$persto['user'].'</b> лишается права пользоваться форумом на '.$timemolch." (<b>".$ispoln."</b>). <b>Причина: </b>".$reason,0,'','*',0); 		echo 'Персонаж <b>'.$persto['user'].'</b> лишается права пользоваться форумом на '.$timemolch.' (<b>'.$perswho['user'].'</b>). <b>Причина: </b>'.$reason;	}	elseif ($persto['silence_forum']>tme())	{		$db->sql("INSERT INTO `puns` ( `uid` , `date` , `who` , `type` ) VALUES (".$persto['uid'].", ".tme().", '".$perswho['user']."', '18');");		set_vars ('`silence_forum`=0', $persto['uid']);		say_to_chat('z','Персонаж <b>'.$persto['user'].'</b> снова обрёл дар речи (<b>'.$ispoln.'</b>).',0,'','*',0); 		echo 'C персонажа <b>'.$persto['user'].'</b> снят запрет пользоваться форумом (<b>'.$perswho['user'].'</b>)';	}}function diler($persto,$perswho,$count,$koment){	GLOBAL $_NG,$you,$db;	$count = mtrunc(intval($count));	if ($count>$perswho['dreserv']) $count = $perswho['dreserv'];	if ($count>0)	{		$res_count = $count;		if($_NG) $res_count = $res_count/2; 		set_vars ("`dmoney`=dmoney+'".$count."'",$persto['uid']);		set_vars ("`dreserv`=dreserv-'".$res_count."'",$perswho['uid']);		$you['dreserv']-=$res_count;		echo 'Продано <b>'.$count.' Бр</b> <i class=red>(Потрачено '.$res_count.' резерва)</i>.';		if (!empty($koment)) echo '<br /><b>Коментарий</b>: '.$koment;		say_to_chat('s','Персонаж <b>'.$perswho['user'].'</b> (Официальный дилер проекта) продал вам <b>'.$count.' Бр.</b>',1,$persto['user'],'*',0); 		$db->sql("INSERT INTO `dtransfer` ( `uid` , `uidwho` , `date` , `summ` , `text` ) VALUES ('".$persto['uid']."', '".$perswho['uid']."', '".tme()."', '".$count."', '".$koment."');");	}}?>